"use client";

/*
 * Loads the study content generated by `npm run ingest` from /content/*.json.
 *
 * Questions for all papers load together (a few MB), because Today's queue
 * and the tracker need all of them. Flashcards are larger and load per paper
 * when a cards screen asks for them. The service worker caches both, so after
 * the first visit they open offline.
 */

import { useSyncExternalStore } from "react";
import type { PaperId } from "@/content/taxonomy";
import { indexBank, type BankIndex } from "./bank";
import type { ContentManifest, Flashcard, Question } from "./content-types";

export type ContentStatus = "loading" | "ready" | "missing" | "error";

export interface ContentSnapshot {
  status: ContentStatus;
  manifest: ContentManifest | null;
  bank: BankIndex | null;
  /** Loaded flashcards per paper. Absent = not loaded yet. */
  cards: Partial<Record<PaperId, Flashcard[]>>;
}

let snapshot: ContentSnapshot = { status: "loading", manifest: null, bank: null, cards: {} };
let started = false;
const loadingCards = new Set<PaperId>();
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
const set = (patch: Partial<ContentSnapshot>) => {
  snapshot = { ...snapshot, ...patch };
  emit();
};

async function fetchJson<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok) throw Object.assign(new Error(`${path}: ${res.status}`), { status: res.status });
  return (await res.json()) as T;
}

async function load() {
  try {
    const manifest = await fetchJson<ContentManifest>("/content/manifest.json");
    const parts = await Promise.all(
      manifest.questionFiles.map((f) => fetchJson<Question[]>(`/content/${f.file}`)),
    );
    set({ status: "ready", manifest, bank: indexBank(parts.flat()) });
  } catch (e) {
    set({ status: (e as { status?: number }).status === 404 ? "missing" : "error" });
  }
}

function subscribe(l: () => void) {
  listeners.add(l);
  if (!started) {
    started = true;
    void load();
  }
  return () => listeners.delete(l);
}

const serverSnapshot: ContentSnapshot = { status: "loading", manifest: null, bank: null, cards: {} };

export function useContent(): ContentSnapshot {
  return useSyncExternalStore(subscribe, () => snapshot, () => serverSnapshot);
}

/** Current bank, or null before it has loaded. For actions outside React. */
export function getBank(): BankIndex | null {
  return snapshot.bank;
}

/** Ask for flashcards of some papers. Safe to call on every render. */
export function requestCards(papers: PaperId[]) {
  const manifest = snapshot.manifest;
  if (!manifest) return;
  for (const p of papers) {
    if (snapshot.cards[p] || loadingCards.has(p)) continue;
    const f = manifest.cardFiles.find((x) => x.paperId === p);
    if (!f) continue;
    loadingCards.add(p);
    fetchJson<Flashcard[]>(`/content/${f.file}`)
      .then((list) => set({ cards: { ...snapshot.cards, [p]: list } }))
      .catch(() => loadingCards.delete(p));
  }
}

/** Test hook. */
export function __setContentForTests(questions: Question[], manifest: ContentManifest | null = null) {
  snapshot = { status: "ready", manifest, bank: indexBank(questions), cards: {} };
  started = true;
}
